tool_calls:
awk -F',' '
BEGIN { OFS=": " }
NR==FNR {
    if (NR > 1) {
        cat[$1] = $3
        price[$1] = $4
    }
    next
}
FNR > 1 {
    pid = $2
    qty = $3
    if (pid in cat) {
        rev[cat[pid]] += qty * price[pid]
    }
}
END {
    for (c in rev) {
        print c, rev[c]
    }
}' /data/products.csv /data/orders.csv | sort -t':' -k2 -nr

